# EXIF map table and callers of the raw orientation getter.
# Read-only. Do not edit this file after it has run.
from pathlib import Path

BASE = 0x60021020
img = Path('inputs/00_0100_50000020.decoded.bin').read_bytes()
n = len(img)


def s32(o):
    v = int.from_bytes(img[o:o + 4], 'little')
    return v - 0x100000000 if v & 0x80000000 else v


def s16(o):
    v = int.from_bytes(img[o:o + 2], 'little')
    return v - 0x10000 if v & 0x8000 else v


lines = []
off = 0x60357E68 - BASE
chunk = img[off:off + 20]
halfs = [int.from_bytes(chunk[i:i + 2], 'little') for i in range(0, 20, 2)]
lines.append(f'table 0x60357e68 bytes {chunk.hex()} halfwords {halfs}')

targets = {
    0x60077E01: 'raw-get',
    0x6006A8AB: 'sample-issue',
    0x6006A887: 'sample-setup',
    0x6006A436: 'acc-init',
    0x6006F3A5: 'sync-read',
    0x6006F3BB: 'sync-write',
    0x6006F39A: 'sync-close',
    0x6006F1BF: 'sync-open',
    0x6006A995: 'sampler-wait',
}
hits = {name: [] for name in targets.values()}
i = 0
while i < n - 6:
    op = img[i]
    pc = BASE + i
    found = None
    if op == 0xDD and i + 7 <= n:
        found = (pc + s32(i + 1)) & 0xFFFFFFFF
    elif op == 0xCD and i + 5 <= n:
        found = (pc + s16(i + 1)) & 0xFFFFFFFF
    name = targets.get(found)
    if name and len(hits[name]) < 30:
        hits[name].append(f'{pc:08x}')
    i += 1
for name, pcs in hits.items():
    lines.append(f'{name} {len(pcs)} {" ".join(pcs)}')
text = '\n'.join(lines) + '\n'
Path('work/out/scan-table-s3.txt').write_text(text, encoding='utf-8')
print(text)
